insert into problems(lesson_id,sort,title,input,output,solution,explanation,solution2,explanation2) values
(215,231,E'Outliers by z-score',E'10 12 11 13 12 95',E'[95]',E'import statistics as st\na = list(map(int, input().split()))\nm, s = st.mean(a), st.pstdev(a)\nprint([x for x in a if abs(x - m) / s > 2])',E'|x - mean| / stdev > 2 అయితే outlier.',E'import math\na = list(map(int, input().split()))\nm = sum(a) / len(a)\ns = math.sqrt(sum((x - m) ** 2 for x in a) / len(a))\nprint([x for x in a if abs(x - m) / s > 2])',E'statistics లేకుండా formula తో.'),
(215,232,E'Longest win streak',E'W W L W W W L',E'3',E'from itertools import groupby\nprint(max((len(list(g)) for k, g in groupby(input().split()) if k == ''W''), default=0))',E'groupby వరుస runs; W runs పొడవు.',E'best = cur = 0\nfor r in input().split():\n    cur = cur + 1 if r == ''W'' else 0\n    best = max(best, cur)\nprint(best)',E'Running counter, L వస్తే reset.'),
(215,233,E'Grid paths with obstacles',E'3 3\n0 0 0\n0 1 0\n0 0 0',E'2',E'from functools import lru_cache\nr, c = map(int, input().split())\ng = [list(map(int, input().split())) for _ in range(r)]\n@lru_cache(None)\ndef f(i, j):\n    if i >= r or j >= c or g[i][j]:\n        return 0\n    if i == r - 1 and j == c - 1:\n        return 1\n    return f(i + 1, j) + f(i, j + 1)\nprint(f(0, 0))',E'Top-down recursion + lru_cache.',E'r, c = map(int, input().split())\ng = [list(map(int, input().split())) for _ in range(r)]\ndp = [[0] * c for _ in range(r)]\nfor i in range(r):\n    for j in range(c):\n        if g[i][j]:\n            continue\n        if i == j == 0:\n            dp[i][j] = 1\n        else:\n            dp[i][j] = (dp[i - 1][j] if i else 0) + (dp[i][j - 1] if j else 0)\nprint(dp[-1][-1])',E'Bottom-up table: పైన + ఎడమ నుండి.'),
(215,234,E'Maze shortest path',E'3 3\n0 0 0\n1 1 0\n0 0 0',E'4',E'from collections import deque\nr, c = map(int, input().split())\ng = [list(map(int, input().split())) for _ in range(r)]\nq = deque([(0, 0, 0)])\nseen = {(0, 0)}\nans = -1\nwhile q:\n    i, j, d = q.popleft()\n    if (i, j) == (r - 1, c - 1):\n        ans = d\n        break\n    for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):\n        if 0 <= a < r and 0 <= b < c and not g[a][b] and (a, b) not in seen:\n            seen.add((a, b))\n            q.append((a, b, d + 1))\nprint(ans)',E'BFS: unweighted graph లో shortest path.',E'import heapq\nr, c = map(int, input().split())\ng = [list(map(int, input().split())) for _ in range(r)]\ndist = {(0, 0): 0}\nh = [(0, 0, 0)]\nans = -1\nwhile h:\n    d, i, j = heapq.heappop(h)\n    if (i, j) == (r - 1, c - 1):\n        ans = d\n        break\n    if d > dist[(i, j)]:\n        continue\n    for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):\n        if 0 <= a < r and 0 <= b < c and not g[a][b] and d + 1 < dist.get((a, b), 10 ** 9):\n            dist[(a, b)] = d + 1\n            heapq.heappush(h, (d + 1, a, b))\nprint(ans)',E'Dijkstra (weights 1): heap తో; weighted కి విస్తరించవచ్చు.'),
(216,235,E'Pagination range',E'25 10 3',E'21 25',E'total, per, page = map(int, input().split())\nprint((page - 1) * per + 1, min(page * per, total))',E'చివరి page లో end = total.',E'total, per, page = map(int, input().split())\nchunk = list(range(1, total + 1))[(page - 1) * per:page * per]\nprint(chunk[0], chunk[-1])',E'Slicing తో page items తీసి మొదటి/చివరి.'),
(216,236,E'Sliding-window rate limiter',E'2 5\n1 2 3 7 8',E'True True False True True',E'from collections import deque\nk, w = map(int, input().split())\nq = deque()\nres = []\nfor t in map(int, input().split()):\n    while q and q[0] <= t - w:\n        q.popleft()\n    if len(q) < k:\n        q.append(t)\n        res.append(True)\n    else:\n        res.append(False)\nprint(*res)',E'Window బయటి పాత requests తొలగించి count < k అయితే allow.',E'k, w = map(int, input().split())\nallowed = []\nres = []\nfor t in map(int, input().split()):\n    recent = [x for x in allowed if x > t - w]\n    if len(recent) < k:\n        allowed.append(t)\n        res.append(True)\n    else:\n        res.append(False)\nprint(*res)',E'Deque లేకుండా: ప్రతిసారి recent filter (O(n)).'),
(216,237,E'Flatten nested JSON',E'{"a": {"b": 1, "c": {"d": 2}}, "e": 3}',E'{''a.b'': 1, ''a.c.d'': 2, ''e'': 3}',E'import json\ndef flat(d, p=''''):\n    out = {}\n    for k, v in d.items():\n        key = p + k\n        if isinstance(v, dict):\n            out.update(flat(v, key + ''.''))\n        else:\n            out[key] = v\n    return out\nprint(flat(json.loads(input())))',E'Dict అయితే recursion, prefix తో keys కలిపాం.',E'import json\nout = {}\nst = [('''', json.loads(input()))]\nwhile st:\n    p, d = st.pop()\n    for k, v in d.items():\n        if isinstance(v, dict):\n            st.append((p + k + ''.'', v))\n        else:\n            out[p + k] = v\nprint(dict(sorted(out.items())))',E'Explicit stack (recursion లేదు); చివరికి keys sort.'),
(216,238,E'Parse query with repeated keys',E'a=1&b=x&a=2&c=',E'{''a'': [''1'', ''2''], ''b'': [''x'']}',E'from urllib.parse import parse_qs\nprint(parse_qs(input()))',E'parse_qs repeated keys list చేస్తుంది, empty values వదులుతుంది.',E'd = {}\nfor part in input().split(''&''):\n    k, _, v = part.partition(''='')\n    if v:\n        d.setdefault(k, []).append(v)\nprint(d)',E'Manual: partition(''='') మరియు setdefault.'),
(216,239,E'Exponential backoff schedule',E'5 100 500',E'[100, 200, 400, 500, 500]',E'n, base, cap = map(int, input().split())\nprint([min(cap, base * 2 ** i) for i in range(n)])',E'delay = base·2^i, cap తో పరిమితి.',E'n, base, cap = map(int, input().split())\nd, out = base, []\nfor _ in range(n):\n    out.append(min(d, cap))\n    d *= 2\nprint(out)',E'ప్రతిసారి రెట్టింపు చేస్తూ loop.'),
(216,240,E'Token bucket limiter',E'3 1\n0 0 0 0 1 2',E'True True True False True True',E'cap, rate = map(int, input().split())\ntokens, last = cap, 0\nres = []\nfor t in map(int, input().split()):\n    tokens = min(cap, tokens + (t - last) * rate)\n    last = t\n    if tokens >= 1:\n        tokens -= 1\n        res.append(True)\n    else:\n        res.append(False)\nprint(*res)',E'సమయం గడిచిన కొద్దీ tokens refill (cap వరకు).',E'class Bucket:\n    def __init__(self, cap, rate):\n        self.cap, self.rate, self.tokens, self.last = cap, rate, cap, 0\n    def allow(self, t):\n        self.tokens = min(self.cap, self.tokens + (t - self.last) * self.rate)\n        self.last = t\n        ok = self.tokens >= 1\n        self.tokens -= ok\n        return ok\ncap, rate = map(int, input().split())\nb = Bucket(cap, rate)\nprint(*[b.allow(t) for t in map(int, input().split())])',E'అదే logic class లో encapsulate.'),
(216,241,E'Aggregate records by field',E'[{"city":"A","amt":10},{"city":"B","amt":5},{"city":"A","amt":7}]',E'{''A'': 17, ''B'': 5}',E'import json\nfrom collections import defaultdict\nd = defaultdict(int)\nfor r in json.loads(input()):\n    d[r[''city'']] += r[''amt'']\nprint(dict(d))',E'defaultdict(int) తో totals.',E'import json\nfrom itertools import groupby\nrs = sorted(json.loads(input()), key=lambda r: r[''city''])\nprint({k: sum(r[''amt''] for r in g) for k, g in groupby(rs, key=lambda r: r[''city''])})',E'Sort చేసి groupby (groupby కి sorted input తప్పనిసరి).'),
(216,242,E'Status code retry decision',E'200 404 500 503 429',E'[''success'', ''client error'', ''retry'', ''retry'', ''retry'']',E'out = []\nfor c in map(int, input().split()):\n    if c == 429 or c >= 500:\n        out.append(''retry'')\n    elif c >= 400:\n        out.append(''client error'')\n    else:\n        out.append(''success'')\nprint(out)',E'429 మరియు 5xx retry చేయాలి; 4xx client తప్పు.',E'cls = {2: ''success'', 4: ''client error'', 5: ''retry''}\nprint([''retry'' if c == 429 else cls[c // 100] for c in map(int, input().split())])',E'c // 100 తో class; 429 మాత్రమే exception.'),
(216,243,E'Validate JSON against schema',E'{"name": "Al", "age": "x"}',E'[''age: expected int'']',E'import json\nschema = {''name'': str, ''age'': int}\nd = json.loads(input())\nerrs = []\nfor k, t in schema.items():\n    if k not in d:\n        errs.append(f''{k}: missing'')\n    elif not isinstance(d[k], t):\n        errs.append(f''{k}: expected {t.__name__}'')\nprint(errs)',E'Fields missing లేదా type తప్పు అయితే error.',E'import json\nschema = {''name'': str, ''age'': int}\nd = json.loads(input())\nprint([f''{k}: missing'' if k not in d else f''{k}: expected {t.__name__}'' for k, t in schema.items() if k not in d or not isinstance(d[k], t)])',E'అదే logic ఒక comprehension లో.'),
(216,244,E'TTL cache',E'5\nput a 1 0\nget a 3\nget a 12\nput b 2 5\nget b 6',E'1\n-1\n2',E'ttl = 10\nn = int(input())\nd = {}\nfor _ in range(n):\n    op = input().split()\n    if op[0] == ''put'':\n        d[op[1]] = (int(op[2]), int(op[3]) + ttl)\n    else:\n        v = d.get(op[1])\n        print(v[0] if v and int(op[2]) < v[1] else -1)',E'Lazy expiry: get చేసినప్పుడు expiry చూస్తాం.',E'import heapq\nttl = 10\nn = int(input())\nd, h = {}, []\nfor _ in range(n):\n    op = input().split()\n    t = int(op[3] if op[0] == ''put'' else op[2])\n    while h and h[0][0] <= t:\n        e, k = heapq.heappop(h)\n        if k in d and d[k][1] == e:\n            del d[k]\n    if op[0] == ''put'':\n        d[op[1]] = (int(op[2]), t + ttl)\n        heapq.heappush(h, (t + ttl, op[1]))\n    else:\n        print(d[op[1]][0] if op[1] in d else -1)',E'Eager purge: heap తో గడువు తీరినవి ముందే తొలగింపు.'),
(217,245,E'Route with parameters',E'/user/7/post/42',E'{''id'': ''7'', ''pid'': ''42''}',E'pattern = ''/user/<id>/post/<pid>''\npath = input()\np1 = pattern.strip(''/'').split(''/'')\np2 = path.strip(''/'').split(''/'')\nout = {}\nfor a, b in zip(p1, p2):\n    if a.startswith(''<''):\n        out[a[1:-1]] = b\n    elif a != b:\n        out = None\n        break\nprint(out if out is not None and len(p1) == len(p2) else ''404'')',E'<name> segments values capture; static segments సరిపోవాలి.',E'import re\npattern = ''/user/<id>/post/<pid>''\nrx = re.sub(r''<(\\w+)>'', r''(?P<\\1>[^/]+)'', pattern)\nm = re.fullmatch(rx, input())\nprint(m.groupdict() if m else ''404'')',E'Pattern ని regex named groups గా మార్చాం.'),
(217,246,E'Role-based access decorator',E'guest',E'403 Forbidden',E'def require(role):\n    def deco(f):\n        def w(user):\n            return f(user) if user == role else ''403 Forbidden''\n        return w\n    return deco\n@require(''admin'')\ndef dash(user):\n    return f''Welcome {user}''\nprint(dash(input()))',E'Decorator with argument: role సరిపోకపోతే 403.',E'user = input()\nclass Require:\n    def __init__(self, role):\n        self.role = role\n    def __call__(self, f):\n        return lambda u: f(u) if u == self.role else ''403 Forbidden''\n@Require(''admin'')\ndef dash(u):\n    return f''Welcome {u}''\nprint(dash(user))',E'Class-based decorator: __call__ తో.'),
(217,247,E'Parse form body',E'name=Nihar+D&age=25&lang=te',E'{''name'': ''Nihar D'', ''age'': ''25'', ''lang'': ''te''}',E'from urllib.parse import parse_qs\nd = parse_qs(input())\nprint({k: v[0] for k, v in d.items()})',E'parse_qs + ను space గా, values list గా ఇస్తుంది.',E'from urllib.parse import unquote_plus\nprint({k: unquote_plus(v) for k, v in (p.split(''='') for p in input().split(''&''))})',E'Manual split + unquote_plus (+ → space).'),
(217,248,E'Route table with methods',E'POST /login',E'login submit',E'routes = {(''GET'', ''/''): ''home'', (''GET'', ''/login''): ''login form'', (''POST'', ''/login''): ''login submit''}\nm, p = input().split()\nif (m, p) in routes:\n    print(routes[(m, p)])\nelif any(rp == p for _, rp in routes):\n    print(''405 Method Not Allowed'')\nelse:\n    print(''404 Not Found'')',E'(method, path) key; path ఉండి method లేకపోతే 405.',E'routes = []\ndef route(p, methods=(''GET'',)):\n    def d(f):\n        routes.append((p, methods, f))\n        return f\n    return d\n@route(''/'')\ndef home(m):\n    return ''home''\n@route(''/login'', methods=(''GET'', ''POST''))\ndef login(m):\n    return ''login submit'' if m == ''POST'' else ''login form''\nm, p = input().split()\nres = ''404 Not Found''\nfor rp, ms, f in routes:\n    if rp == p:\n        res = f(m) if m in ms else ''405 Method Not Allowed''\nprint(res)',E'@route(methods=[...]) decorator తో registry (Flask లాగే).'),
(217,249,E'Signed cookie',E'user=nihar',E'True False',E'import hmac, hashlib\nsecret = b''k''\ndata = input()\nsig = hmac.new(secret, data.encode(), hashlib.sha256).hexdigest()\nok = lambda d, s: hmac.compare_digest(hmac.new(secret, d.encode(), hashlib.sha256).hexdigest(), s)\nprint(ok(data, sig), ok(data + ''x'', sig))',E'HMAC: data మారితే signature సరిపోదు; compare_digest timing attacks నుండి కాపాడుతుంది.',E'import hashlib\nsecret = ''k''\ndata = input()\nsign = lambda d: hashlib.sha256((secret + d).encode()).hexdigest()\nsig = sign(data)\nprint(sign(data) == sig, sign(data + ''x'') == sig)',E'Simple secret+data hash: పనిచేస్తుంది కానీ HMAC సురక్షితం.'),
(217,250,E'Template with escaping',E'Hi {{name}}\nname=<b>Nihar</b>',E'Hi &lt;b&gt;Nihar&lt;/b&gt;',E'import re, html\ntpl = input()\nctx = dict(kv.split(''='', 1) for kv in input().split())\nprint(re.sub(r''\\{\\{(\\w+)\\}\\}'', lambda m: html.escape(ctx[m.group(1)]), tpl))',E'Values escape చేయడం XSS నుండి కాపాడుతుంది (Jinja autoescape లాగే).',E'import html\ntpl = input()\nfor kv in input().split():\n    k, v = kv.split(''='', 1)\n    tpl = tpl.replace(''{{'' + k + ''}}'', html.escape(v))\nprint(tpl)',E'ప్రతి key కి replace.'),
(217,251,E'JSON CRUD API',E'5\nPOST apple\nPOST pear\nGET 1\nDELETE 1\nGET 1',E'201 id=1\n201 id=2\n200 apple\n204\n404',E'n = int(input())\nstore, nid = {}, 1\nfor _ in range(n):\n    op = input().split()\n    if op[0] == ''POST'':\n        store[nid] = op[1]\n        print(f''201 id={nid}'')\n        nid += 1\n    elif op[0] == ''GET'':\n        print(f''200 {store[int(op[1])]}'' if int(op[1]) in store else ''404'')\n    else:\n        print(''204'' if store.pop(int(op[1]), None) else ''404'')',E'Status codes: 201 Created, 200 OK, 204 No Content, 404.',E'class API:\n    def __init__(self):\n        self.s, self.n = {}, 1\n    def handle(self, m, a):\n        if m == ''POST'':\n            self.s[self.n] = a\n            self.n += 1\n            return f''201 id={self.n - 1}''\n        i = int(a)\n        if i not in self.s:\n            return ''404''\n        if m == ''GET'':\n            return f''200 {self.s[i]}''\n        del self.s[i]\n        return ''204''\napi = API()\nfor _ in range(int(input())):\n    m, a = input().split()\n    print(api.handle(m, a))',E'Class లో state + handle(method, arg).'),
(217,252,E'Middleware chain order',E'3',E'before 1\nbefore 2\nbefore 3\nhandler\nafter 3\nafter 2\nafter 1',E'def handler():\n    print(''handler'')\ndef mw(i, nxt):\n    def run():\n        print(''before'', i)\n        nxt()\n        print(''after'', i)\n    return run\nf = handler\nfor i in range(int(input()), 0, -1):\n    f = mw(i, f)\nf()',E'Closures తో లోపలి నుండి wrap; బయటి middleware ముందు run.',E'n = int(input())\ndef run(i):\n    if i > n:\n        print(''handler'')\n        return\n    print(''before'', i)\n    run(i + 1)\n    print(''after'', i)\nrun(1)',E'Recursion: లోపలికి వెళ్ళేటప్పుడు before, తిరిగి వచ్చేటప్పుడు after.'),
(217,253,E'url_for builder',E'/user/<id>/post/<pid>\nid=7 pid=42 page=2',E'/user/7/post/42?page=2',E'from urllib.parse import urlencode\nrule = input()\nargs = dict(kv.split(''='') for kv in input().split())\nextra = {}\nfor k, v in args.items():\n    if ''<'' + k + ''>'' in rule:\n        rule = rule.replace(''<'' + k + ''>'', v)\n    else:\n        extra[k] = v\nprint(rule + (''?'' + urlencode(extra) if extra else ''''))',E'Rule లో ఉన్న keys path లో, మిగతావి query string లో.',E'import re\nfrom urllib.parse import urlencode\nrule = input()\nargs = dict(kv.split(''='') for kv in input().split())\nkeys = set(re.findall(r''<(\\w+)>'', rule))\npath = re.sub(r''<(\\w+)>'', lambda m: args[m.group(1)], rule)\nextra = {k: v for k, v in args.items() if k not in keys}\nprint(path + (''?'' + urlencode(extra) if extra else ''''))',E'Regex తో placeholders replace.'),
(217,254,E'Login lockout',E'2\nfail fail ok fail',E'denied denied locked locked',E'mx = int(input())\nfails = 0\nout = []\nfor a in input().split():\n    if fails >= mx:\n        out.append(''locked'')\n    elif a == ''ok'':\n        fails = 0\n        out.append(''granted'')\n    else:\n        fails += 1\n        out.append(''denied'')\nprint(*out)',E'Fails mx చేరాక సరైన password కూడా locked.',E'class Lock:\n    def __init__(self, mx):\n        self.mx, self.f = mx, 0\n    def attempt(self, a):\n        if self.f >= self.mx:\n            return ''locked''\n        if a == ''ok'':\n            self.f = 0\n            return ''granted''\n        self.f += 1\n        return ''denied''\nlk = Lock(int(input()))\nprint(*[lk.attempt(a) for a in input().split()])',E'State class లో; అదే logic.');
